      {
        "title": "カラーパレット",
        "position": "bottom left strip",
        "count": 8,
        "labels": ["髪色", "瞳色", "肌色", "衣装（ベース）", "衣装（影色）", "襟（白）", "アクセント（夜空）", "アクセント（光）"],
        "content": "8 circular color swatches with hex codes beneath"
      },
      {
        "title": "世界観",
        "position": "bottom center box",
        "count": 1,
        "labels": ["— 夜の灯りが導く街 —"],
        "content": "a short Japanese world-setting paragraph"
      }
    ]
